/// <summary>
/// Copy data to target service class
/// </summary>
class ISDAppIntgCopyDataToTargetService extends SysOperationServiceBase
{
    str                 recRange;
    NoYes               errorStatus;
    NoYes               selectedData;
    DMFOperation        selection;

}

Method.Source:
/// <summary>
/// Start of the service class
/// </summary>
/// <param name="_dataContract">The data contract containing the necessary parameters for the operation.</param>
public void startOperation(ISDAppIntgCopyDataToTargetContract _dataContract)
{
    //Option to schedule batch bundling
    //this.batchBundling(_dataContract, 8);

    this.generate(_dataContract);
}

/// <summary>
/// Initialize values from contract class
/// </summary>
/// <param name = "_dataContract">Data contract</param>
public void initFrmContract(ISDAppIntgCopyDataToTargetContract _dataContract)
{
    recRange        = _dataContract.parmDMFDefinitionGroupExecutionRange();
    errorStatus     = _dataContract.parmDMFError();
    selectedData    = _dataContract.parmDMFSelected();
    selection       = _dataContract.parmDMFOperation();
}

/// <summary>
/// Perform batch bundling
/// </summary>
/// <param name="_dataContract">The data contract containing the necessary parameters for the operation.</param>
/// <param name="_numberOfTask">The number of tasks to divide the work into.</param>
public void batchBundling(ISDAppIntgCopyDataToTargetContract _dataContract, int _numberOfTask)
{
    str range;
    int totalNumberOfRecords, recordCount;
    int numberOfTask, numberOfRecordsPerTask;

    Query                   updQuery;
    QueryRun                queryRun;
    QueryBuildDataSource    qbds_dmfDefinitionGroupExecution;

    ISDAppIntgCopyDataToTargetController    controller;
    ISDAppIntgCopyDataToTargetContract      contract;
    BatchHeader                             batchHeader;

    DMFDefinitionGroupExecution     definitionGroupExecution;


    if (this.isExecutingInBatch())
    {
        batchHeader = this.getCurrentBatchHeader();
    }
    else
    {
        batchHeader = BatchHeader::construct();
        batchHeader.parmCaption("@DMF92");
    }

    updQuery                            = _dataContract.getQuery();
    qbds_dmfDefinitionGroupExecution    = updQuery.dataSourceNo(1);
    qbds_dmfDefinitionGroupExecution.addGroupByField(fieldNum(DMFDefinitionGroupExecution, ExecutionId));

    queryRun                = new queryRun(updQuery);
    totalNumberOfRecords    = QueryRun::getQueryRowCount(queryRun.query(), intMax());

    numberOfTask = _numberOfTask ? _numberOfTask : 1;

    if (totalNumberOfRecords > numberOfTask)
    {
        numberOfRecordsPerTask = totalNumberOfRecords div numberOfTask;
    }
    else
    {
        numberOfRecordsPerTask = 1;
    }

    while (queryRun.next())
    {
        definitionGroupExecution = queryRun.get(tableNum(DMFDefinitionGroupExecution));

        range = queryRangeConcat(range, definitionGroupExecution.RecId);

        recordCount++;

        if (recordCount == numberOfRecordsPerTask)
        {
            controller = ISDAppIntgCopyDataToTargetController::newFromArgs(false);
            contract  = controller.getDataContractObject() as ISDAppIntgCopyDataToTargetContract;
            contract.setQuery(_dataContract.getQuery());
            contract.parmDMFDefinitionGroupExecutionRange(range);

            batchHeader.addRuntimeTask(controller, this.getCurrentBatchTask().RecId);

            range = '';
            recordCount = 0;
        }
    }

    if (recordCount)
    {
        controller = ISDAppIntgCopyDataToTargetController::newFromArgs(false);
        contract  = controller.getDataContractObject() as ISDAppIntgCopyDataToTargetContract;
        contract.setQuery(_dataContract.getQuery());
        contract.parmDMFDefinitionGroupExecutionRange(range);

        batchHeader.addRuntimeTask(controller, this.getCurrentBatchTask().RecId);

        range = '';
        recordCount = 0;
    }

    batchHeader.save();

    Info(strFmt("@ISDRetail:CopyDataToTargetBatch", batchHeader.parmBatchHeaderId()));
}

/// <summary>
/// Modify controller query
/// </summary>
/// <param name="_q">The query to be modified.</param>
/// <returns>The modified query.</returns>
public query modifyControllerQuery(Query _q)
{
    QueryBuildDataSource  qbds_dmfDefinitionGroupExecution  = _q.dataSourceNo(1);

    if (recRange)
    {
        List recRangeList = strSplit(recRange, ',');

        qbds_dmfDefinitionGroupExecution.clearRange(fieldNum(DMFDefinitionGroupExecution, RecId));
        SysQuery::findOrCreateRange(qbds_dmfDefinitionGroupExecution, fieldNum(DMFDefinitionGroupExecution, RecId)).value(SysQueryRangeUtil::queryListRange(recRangeList));
    }

    return _q;
}

/// <summary>
/// Generate method
/// </summary>
/// <param name = "_dataContract">Data contract</param>
public void generate(ISDAppIntgCopyDataToTargetContract _dataContract)
{
    boolean                         prepOk, writeOk;
    QueryRun                        queryRun;
    DMFDefinitionGroupExecution     definitionGroupExecution;

    setPrefix("@DMF92");

    this.initFrmContract(_dataContract);

    queryRun = new queryRun(this.modifyControllerQuery(_dataContract.getQuery()));

    while (queryRun.next())
    {
        prepOk = false; 
        writeOk = false; 

        definitionGroupExecution = queryRun.get(tableNum(DMFDefinitionGroupExecution));

        setPrefix(strFmt("@ISDRetail:EntityExecIdInfo", definitionGroupExecution.ExecutionId, definitionGroupExecution.Entity));

        prepOk = this.prepare(definitionGroupExecution);

        if (prepOk)
        {
            writeOk = this.dmfWriteExecutionParameters(definitionGroupExecution);

            if (writeOk)
            {
                this.dmfWriteDataAsync(definitionGroupExecution);
            }
        }
    }
}

/// <summary>
/// Prepare execution ids
/// </summary>
/// <param name="_definitionGroupExecution">The <c>DMFDefinitionGroupExecution</c> buffer.</param>
public boolean prepare(DMFDefinitionGroupExecution _definitionGroupExecution)
{
    boolean                     ok;
    DMFDefinitionGroupExecution definitionGroupExecution, definitionGroupExecutionLoc;

    if (_definitionGroupExecution)
    {
        //Clear the selection of entities in the execution form.
        ttsbegin;
        update_recordset definitionGroupExecution
                setting IsSelected = (NoYes::No), ReRun = (NoYes::No)
                where definitionGroupExecution.ExecutionId      == _definitionGroupExecution.ExecutionId
                   && definitionGroupExecution.DefinitionGroup  == _definitionGroupExecution.DefinitionGroup;
        ttscommit;

        ttsbegin;
        definitionGroupExecutionLoc = DMFDefinitionGroupExecution::find(_definitionGroupExecution.DefinitionGroup, _definitionGroupExecution.Entity, _definitionGroupExecution.ExecutionId, true);

        if (definitionGroupExecutionLoc.RecId)
        {
            definitionGroupExecutionLoc.IsSelected = (NoYes::Yes);
            definitionGroupExecutionLoc.update();
            ok = true;
        }
        ttscommit;
    }

    return ok;
}

public boolean dmfWriteExecutionParameters(DMFDefinitionGroupExecution _definitionGroupExecution)
{
    boolean                         ok;
    DMFExecution                    execution;
    DMFEntity                       dmfEntity;
    DMFDefinitionGroupExecution     definitionGroupExecution;

    ttsBegin;
    while select forUpdate definitionGroupExecution
        where definitionGroupExecution.ExecutionId == _definitionGroupExecution.ExecutionId
            && definitionGroupExecution.DefinitionGroup == _definitionGroupExecution.DefinitionGroup
    {
        dmfEntity = DMFEntity::find(definitionGroupExecution.Entity);

        if(dmfEntity.EntityType != DMFEntityTypes::CompositEntity)
        {
            if(selection == DMFOperation::All)
            {
                definitionGroupExecution.NoOfRecords = DMFEntityWriter::getNumOfRecords(dmfEntity.EntityTable, definitionGroupExecution.executionId,false,false);
            }
            else
            {
                if(SelectedData && !errorStatus)
                {
                    definitionGroupExecution.NoOfRecords = DMFEntityWriter::getNumOfRecords(dmfEntity.EntityTable, definitionGroupExecution.executionId,false,true);
                }
                else if(errorStatus && !SelectedData)
                {
                    definitionGroupExecution.NoOfRecords = DMFEntityWriter::getNumOfRecords(dmfEntity.EntityTable, definitionGroupExecution.executionId,true,false);
                }
                else
                {
                    definitionGroupExecution.NoOfRecords = DMFEntityWriter::getNumOfRecords(dmfEntity.EntityTable, definitionGroupExecution.executionId,true,true);
                }
            }
            definitionGroupExecution.doupdate();
            ok = true;
        }
    }
    ttsCommit;

    return ok;
}

public void dmfWriteDataAsync(DMFDefinitionGroupExecution _definitionGroupExecution)
{
    DMFDefinitionGroupEntity    definitionGroupEntity;
    DMFEntity                   entity;
    DMFDefinitionGroupExecution defGroupExec;

    DMFDefinitionGroupExecution executionLocal;

    ttsbegin;
    update_recordset executionLocal
            setting NoOfThreads = 1
            where executionLocal.ExecutionId == _definitionGroupExecution.ExecutionId
            && executionLocal.IsSelected == NoYes::Yes;
    ttscommit;

    if (_definitionGroupExecution.ExecutionId)
    {
        ttsbegin;
        update_recordset defGroupExec
                setting ReRun = defGroupExec.IsSelected
                where defGroupExec.ExecutionId == _definitionGroupExecution.ExecutionId;
        ttscommit;
    }

    DMFWriteExecutionParameters dmfWriteExecutionParameters = DMFWriteExecutionParameters::construct();

    dmfWriteExecutionParameters.parmDefinitionGroup(_definitionGroupExecution.DefinitionGroup);
    dmfWriteExecutionParameters.parmErrorStatus(errorStatus);
    dmfWriteExecutionParameters.parmExecutionId(_definitionGroupExecution.ExecutionId);
    dmfWriteExecutionParameters.parmSelectedData(selectedData);
    dmfWriteExecutionParameters.parmSkipFormNavigation(true);

    Args args = new Args();
    args.record(_definitionGroupExecution);
    args.parmObject(dmfWriteExecutionParameters);
    args.caller(this);

    new MenuFunction(menuItemActionStr(DMFRunTargetAsync), MenuItemType::Action).run(args);

    info("@ApplicationFoundation:DMFImportJobScheduled");
}
